import * as vscode from 'vscode';
type SampleData = { [dirname: string]: SampleData | ["external", number] | ["internal", string]; }
// eslint-disable-next-line @typescript-eslint/no-var-requires
const samplesdata:SampleData = require('../samples.json');

export class File implements vscode.FileStat {
	public type: vscode.FileType;
	public readonly ctime: number;
	public mtime: number;
	public size: number;

	// name: string;
	// data?: Uint8Array;
	// getData?: () => Promise<Uint8Array>;

	constructor(public uri: vscode.Uri, public name: string, public readonly getData: () =>Promise<Uint8Array>) {
		this.type = vscode.FileType.File;
		this.ctime = Date.now();
		this.mtime = Date.now();
		this.size = 0;
	}
}

export class Directory implements vscode.FileStat {

	type: vscode.FileType;
	ctime: number;
	mtime: number;
	size: number;

	name: string;
	entries: Map<string, File | Directory>;

	constructor(public uri: vscode.Uri, name: string) {
		this.type = vscode.FileType.Directory;
		this.ctime = Date.now();
		this.mtime = Date.now();
		this.size = 0;
		this.name = name;
		this.entries = new Map();
	}
}

export type Entry = File | Directory;
const textEncoder = new TextEncoder();

export class GSFS implements vscode.FileSystemProvider, vscode.Disposable {
	static scheme = 'gsfs';

	private readonly disposable: vscode.Disposable;

	constructor(private readonly baseURL: string) {
		this.disposable = vscode.Disposable.from(
			vscode.workspace.registerFileSystemProvider(GSFS.scheme, this, { isCaseSensitive: true }),
		);
	}

	dispose() {
		this.disposable?.dispose();
	}

	seed() {
		this.createDirectory(vscode.Uri.parse(`gsfs:/samples/`));
		const readSamplesDir = (dir: SampleData, relPath = '') => {
			for (const [name, value] of Object.entries(dir)) {
				if (Array.isArray(value)) {
					const isInternal = value[0] === 'internal';
					const data = isInternal ? value[1] : undefined;
					const encodedData = textEncoder.encode(data);

					this.writeFile(vscode.Uri.parse(`gsfs:/${relPath}/${name}`), encodedData, { create: true, overwrite: true, external: !isInternal, size: isInternal ? encodedData.byteLength : value[1] });
					// typeof data === 'string') {
					// console.log("FILE:", `gsfs:/${relPath}/${name}`);
				} else {
					// console.log("DIRECTORY:", `gsfs:/${relPath}/${name}`);
					this.createDirectory(vscode.Uri.parse(`gsfs:/${relPath}/${name}`));
					readSamplesDir(value, relPath + '/' + name);
				}
			}
		}
		readSamplesDir(samplesdata, "samples");
		return;
	}

	root = new Directory(vscode.Uri.parse('gsfs:/'), '');

	// --- manage file metadata

	stat(uri: vscode.Uri): vscode.FileStat {
		return this._lookup(uri, false);
	}

	readDirectory(uri: vscode.Uri): [string, vscode.FileType][] {
		const entry = this._lookupAsDirectory(uri, false);
		const result: [string, vscode.FileType][] = [];
		for (const [name, child] of entry.entries) {
			result.push([name, child.type]);
		}
		return result;
	}

	// --- manage file contents

	async readFile(uri: vscode.Uri): Promise<Uint8Array> {
		const data = await this._lookupAsFile(uri, false).getData();
		if (data) {
			return data;
		}
		throw vscode.FileSystemError.FileNotFound();
	}

	writeFile(uri: vscode.Uri, content: Uint8Array, options: { create: boolean, overwrite: boolean, external: boolean, size: number }): void {
		const basename = this._basename(uri.path);
		const parent = this._lookupParentDirectory(uri);
		let entry = parent.entries.get(basename);
		if (entry instanceof Directory) {
			throw vscode.FileSystemError.FileIsADirectory(uri);
		}
		if (!entry && !options.create) {
			throw vscode.FileSystemError.FileNotFound(uri);
		}
		if (entry && options.create && !options.overwrite) {
			throw vscode.FileSystemError.FileExists(uri);
		}
		if (!entry) {
			if(options.external) {
				entry = new File(uri, basename, async () => {
					const { path } = uri.toJSON();
					// remove the beginning /samples from path
					const pathWithoutSamples = path.replace(/^\/samples/, '');

					// const windowLocation = vscode
					// console.log(this.baseURL);
					const url = vscode.Uri.joinPath(vscode.Uri.parse(this.baseURL), 'external', pathWithoutSamples).toString();
					// const url = `http://localhost:8000/extensions/samples-fs-extension/external${pathWithoutSamples}`;
					const data = await fetch(url);

					if (!data.ok) { throw new Error(`Failed to get content from ${path}`); }

					const buffer = await data.arrayBuffer();
					return new Uint8Array(buffer);
				});
			} else {
				entry = new File(uri, basename, () => Promise.resolve(content));
			}
			entry.size = options.size;
			parent.entries.set(basename, entry);
			this._fireSoon({ type: vscode.FileChangeType.Created, uri });
		}
		entry.mtime = Date.now();
		// entry.data = content;

		this._fireSoon({ type: vscode.FileChangeType.Changed, uri });
	}

	// --- manage files/folders

	rename(oldUri: vscode.Uri, newUri: vscode.Uri, options: { overwrite: boolean }): void {
		if (!options.overwrite && this._lookup(newUri, true)) {
			throw vscode.FileSystemError.FileExists(newUri);
		}

		const entry = this._lookup(oldUri, false);
		const oldParent = this._lookupParentDirectory(oldUri);

		const newParent = this._lookupParentDirectory(newUri);
		const newName = this._basename(newUri.path);

		oldParent.entries.delete(entry.name);
		entry.name = newName;
		newParent.entries.set(newName, entry);

		this._fireSoon(
			{ type: vscode.FileChangeType.Deleted, uri: oldUri },
			{ type: vscode.FileChangeType.Created, uri: newUri }
		);
	}

	delete(uri: vscode.Uri): void {
		const dirname = uri.with({ path: this._dirname(uri.path) });
		const basename = this._basename(uri.path);
		const parent = this._lookupAsDirectory(dirname, false);
		if (!parent.entries.has(basename)) {
			throw vscode.FileSystemError.FileNotFound(uri);
		}
		parent.entries.delete(basename);
		parent.mtime = Date.now();
		parent.size -= 1;
		this._fireSoon({ type: vscode.FileChangeType.Changed, uri: dirname }, { uri, type: vscode.FileChangeType.Deleted });
	}

	createDirectory(uri: vscode.Uri): void {
		const basename = this._basename(uri.path);
		const dirname = uri.with({ path: this._dirname(uri.path) });
		const parent = this._lookupAsDirectory(dirname, false);

		const entry = new Directory(uri, basename);
		parent.entries.set(entry.name, entry);
		parent.mtime = Date.now();
		parent.size += 1;
		this._fireSoon({ type: vscode.FileChangeType.Changed, uri: dirname }, { type: vscode.FileChangeType.Created, uri });
	}

	// --- lookup

	private _lookup(uri: vscode.Uri, silent: false): Entry;
	private _lookup(uri: vscode.Uri, silent: boolean): Entry | undefined;
	private _lookup(uri: vscode.Uri, silent: boolean): Entry | undefined {
		const parts = uri.path.split('/');
		let entry: Entry = this.root;
		for (const part of parts) {
			if (!part) {
				continue;
			}
			let child: Entry | undefined;
			if (entry instanceof Directory) {
				child = entry.entries.get(part);
			}
			if (!child) {
				if (!silent) {
					throw vscode.FileSystemError.FileNotFound(uri);
				} else {
					return undefined;
				}
			}
			entry = child;
		}
		return entry;
	}

	private _lookupAsDirectory(uri: vscode.Uri, silent: boolean): Directory {
		const entry = this._lookup(uri, silent);
		if (entry instanceof Directory) {
			return entry;
		}
		throw vscode.FileSystemError.FileNotADirectory(uri);
	}

	private _lookupAsFile(uri: vscode.Uri, silent: boolean): File {
		const entry = this._lookup(uri, silent);
		if (entry instanceof File) {
			return entry;
		}
		throw vscode.FileSystemError.FileIsADirectory(uri);
	}

	private _lookupParentDirectory(uri: vscode.Uri): Directory {
		const dirname = uri.with({ path: this._dirname(uri.path) });
		return this._lookupAsDirectory(dirname, false);
	}

	// --- manage file events

	private _emitter = new vscode.EventEmitter<vscode.FileChangeEvent[]>();
	private _bufferedEvents: vscode.FileChangeEvent[] = [];
	private _fireSoonHandle?: any;

	readonly onDidChangeFile: vscode.Event<vscode.FileChangeEvent[]> = this._emitter.event;

	watch(_resource: vscode.Uri): vscode.Disposable {
		// ignore, fires for all changes...
		return new vscode.Disposable(() => { return; });
	}

	private _fireSoon(...events: vscode.FileChangeEvent[]): void {
		this._bufferedEvents.push(...events);

		if (this._fireSoonHandle) {
			clearTimeout(this._fireSoonHandle);
		}

		this._fireSoonHandle = setTimeout(() => {
			this._emitter.fire(this._bufferedEvents);
			this._bufferedEvents.length = 0;
		}, 5);
	}

	// --- path utils

	private _basename(path: string): string {
		path = this._rtrim(path, '/');
		if (!path) {
			return '';
		}

		return path.substr(path.lastIndexOf('/') + 1);
	}

	private _dirname(path: string): string {
		path = this._rtrim(path, '/');
		if (!path) {
			return '/';
		}

		return path.substr(0, path.lastIndexOf('/'));
	}

	private _rtrim(haystack: string, needle: string): string {
		if (!haystack || !needle) {
			return haystack;
		}

		const needleLen = needle.length,
			haystackLen = haystack.length;

		if (needleLen === 0 || haystackLen === 0) {
			return haystack;
		}

		let offset = haystackLen,
			idx = -1;

		// eslint-disable-next-line no-constant-condition
		while (true) {
			idx = haystack.lastIndexOf(needle, offset - 1);
			if (idx === -1 || idx + needleLen !== offset) {
				break;
			}
			if (idx === 0) {
				return '';
			}
			offset = idx;
		}

		return haystack.substring(0, offset);
	}

	private _getFiles(): Set<File> {
		const files = new Set<File>();

		this._doGetFiles(this.root, files);

		return files;
	}

	private _doGetFiles(dir: Directory, files: Set<File>): void {
		dir.entries.forEach(entry => {
			if (entry instanceof File) {
				files.add(entry);
			} else {
				this._doGetFiles(entry, files);
			}
		});
	}
}