import * as vscode from 'vscode';
import { GSFS } from './gsfs';

declare const navigator: unknown;

export async function activate(context: vscode.ExtensionContext) {
	if (typeof navigator === 'object') { // do not run under node.js
		const searchLocation: string = await vscode.commands.executeCommand('gamma-samples-extension.location', 'get', 'search') as string;
		const baseURL: string = await vscode.commands.executeCommand('gamma-samples-extension.location', 'get', 'origin') as string;
		const path = await vscode.commands.executeCommand('gamma-samples-extension.location', 'get', 'pathname') as string;

		const extensionURL = vscode.Uri.joinPath(vscode.Uri.parse(baseURL), path, 'extensions', 'samples-fs-extension');
		console.log(extensionURL.toString());

		const gsfs = enableFs(context, extensionURL.toString());
		gsfs.seed();


		const params = new URLSearchParams(searchLocation);
		if (params.has('path')) {
			const path = params.get('path');
			vscode.commands.executeCommand('vscode.open', vscode.Uri.parse(`gsfs:/samples/${path}`));
		} else {
			vscode.commands.executeCommand('vscode.open', vscode.Uri.parse(`gsfs:/samples/README.webnb`));
		}

		// if no directory is open, open the samples directory
		if (vscode.workspace.workspaceFolders === undefined) {
			vscode.commands.executeCommand('vscode.openFolder', vscode.Uri.parse('gsfs:/samples'), {forceReuseWindow: true});
		}
	}
}

function enableFs(context: vscode.ExtensionContext, baseURL: string): GSFS {
	const gsfs = new GSFS(baseURL);
	context.subscriptions.push(gsfs);

	return gsfs;
}